+template<int Paid>
+void launch_plan(torch::Tensor q,torch::Tensor w,torch::Tensor capture,
+                 const std::vector<torch::Tensor>& p,torch::Tensor budget) {
+  // Six owned fields: FP8 fine[Q,Paid+2,128], F32 scales/meta/raw/out and
+  // I32 validity hints. Paid-head IDs and support masks remain local to the plan.
