+      static_cast<const uint8_t*>(q.data_ptr()),w.data_ptr<float>(),
+      reinterpret_cast<const dosa_geometry::UnsignedHeadMask*>(capture.data_ptr<dosa_geometry::HeadMask>()),
+      p[0].data_ptr<uint8_t>(),p[1].data_ptr<float>(),p[2].data_ptr<float>(),
+      p[3].data_ptr<float>(),p[4].data_ptr<float>(),p[5].data_ptr<int>(),budget.data_ptr<int>());
+  C10_CUDA_KERNEL_LAUNCH_CHECK();
