+// Host selects an existing budget specialization; the per-query early return
+// consumes only device tags, so no host query decision or reorder is introduced.
+void plan128(int64_t paid,torch::Tensor q,torch::Tensor w,torch::Tensor capture,
+          std::vector<torch::Tensor> outputs,torch::Tensor budget) {
+  c10::cuda::CUDAGuard guard(q.device());
+  // Q[Q,H,128], F32[Q,H] weights, masks[Q,129] and I32[Q/8] budgets
+  // belong to the owner and remain alive through this current-stream launch.
+  if(paid==14)launch_plan<14>(q,w,capture,outputs,budget);
+  else if(paid==16)launch_plan<16>(q,w,capture,outputs,budget);
+  else if(paid==20)launch_plan<20>(q,w,capture,outputs,budget);
+  else if(paid==28){
+    if constexpr(dosa_geometry::Heads==64)launch_plan<28>(q,w,capture,outputs,budget);
+    else TORCH_CHECK(false,"Paid28 requires H64");
+  }
+  else TORCH_CHECK(false,"unsupported paid budget");
+}
