+
+__device__ void fail(const Args& a,int row) {
+  if(threadIdx.x==0) {
+    atomicOr(a.error+row,1);
+    a.boundary_counts[row]=0;
+    for(int j=0;j<2;++j)a.diag[int64_t(row)*2+j]=-1;
+  }
+  for(int j=threadIdx.x;j<Top;j+=Threads)a.output[int64_t(row)*Top+j]=-1;
+}
