+void select_dense5(torch::Tensor low,torch::Tensor packed,torch::Tensor counts,torch::Tensor starts,torch::Tensor ends,
+    torch::Tensor epsilon,torch::Tensor pool_status,torch::Tensor error,torch::Tensor output,
