+    torch::Tensor temporary,torch::Tensor temporary_ids,int64_t nk) {
+  // Every tensor is constructor-owned: U8/I32[Q,114688] frontier planes,
+  // I32[Q,2048] output, I32[Q,4096] boundary, F32/I32[Q,8192] temporary
+  // rows, I32[Q,2] B/E fields and independent metadata. Selection reads counts
+  // and error bits on the current stream; no caller tensor is borrowed here.
+  const int rows=packed.size(0),cap=packed.size(1);
+  record4_integer::Args args{packed.data_ptr<int>(),counts.data_ptr<int>(),starts.data_ptr<int>(),ends.data_ptr<int>(),
+      pool_status.data_ptr<int>(),epsilon.data_ptr<float>(),error.data_ptr<int>(),output.data_ptr<int>(),
+      diag.data_ptr<int>(),boundary_ids.data_ptr<int>(),boundary_counts.data_ptr<int>(),temporary.data_ptr<float>(),
+      temporary_ids.data_ptr<int>(),rows,cap,int(nk),4096,int(temporary.size(1)),low.data_ptr<uint8_t>()};
+  c10::cuda::CUDAGuard guard(packed.device());
+  record4_integer::select<<<rows,256,0,c10::cuda::getCurrentCUDAStream()>>>(args);
+  C10_CUDA_KERNEL_LAUNCH_CHECK();
+}
